2	import fs from 'node:fs';
3	import path from 'node:path';
4	import { SEL } from './contract.ts';
5	import { addNote, armPage, openApp } from './drive.ts';
6	import { ROOT } from './arms.ts';
7	
8	// The functional parity guard. Both arms must pass this unchanged.
